// Справочник городов России — статический датасет, импортированный один раз
// сид-скриптом (prisma/seed.ts) в таблицу RuCity. Источник — открытый датасет
// hflabs/city (https://github.com/hflabs/city, CC-BY-SA 4.0), тот же
// поставщик данных, что и DaData (которым уже размечены сами объявления —
// см. AddressInput/Ad.regionIsoCode/localityFiasId). Нужен для того, чтобы
// фильтр локации в каталоге подсказывал города СРАЗУ при вводе ("Моск..." →
// "Москва"), даже если по этому городу ещё нет ни одного объявления — в
// отличие от AdsService.getAvailableLocations(), которая иначе строит список
// только по реальным опубликованным объявлениям. Сёла/деревни сюда
// намеренно не включены (в исходном датасете их нет) — для них фильтр
// по-прежнему работает только там, где уже есть реальное объявление.
//
// ISO 3166-2:RU коды регионов сюда намеренно НЕ добавлены — не удалось
// надёжно подтвердить точный формат (см. обсуждение), поэтому города
// федерального значения (Москва/СПб/Севастополь) в AdsService матчатся по
// названию региона (ILIKE), а не по ISO-коду.
export interface RuCityInput {
  fiasId: string
  city: string
  cityType: string | null
  region: string
  regionType: string | null
  isFederalCity: boolean
  lat: number
  lng: number
}

